 57	export function openStateStream(callbacks: {
 58	  onSnapshot: (snapshot: Snapshot) => void
 59	  onOpen?: () => void
 60	  onError?: (message: string) => void
 61	  onClose?: () => void
 62	}): WebSocket {
 63	  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
 64	  const socket = new WebSocket(`${protocol}//${window.location.host}/api/v1/stream`)
 65	  socket.addEventListener('open', () => callbacks.onOpen?.())
 66	  socket.addEventListener('message', (event) => {
 67	    try {
 68	      const value: unknown = JSON.parse(String(event.data))
 69	      if (!isSnapshot(value)) throw new ApiError('State stream returned an invalid snapshot')
 70	      callbacks.onSnapshot(value)
 71	    } catch (error) {
 72	      callbacks.onError?.(error instanceof Error ? error.message : 'State stream failed')
 73	      socket.close(1002, 'invalid snapshot')
 74	    }
 75	  })
 76	  socket.addEventListener('error', () => {
 77	    callbacks.onError?.('Live state stream disconnected; using HTTP fallback')
 78	    if (socket.readyState === WebSocket.OPEN) socket.close(1011, 'stream transport error')
 79	  })
 80	  socket.addEventListener('close', () => callbacks.onClose?.())
 81	  return socket
 82	}
